    try:
        txt=open(f,'r',encoding='utf-8').read()
    except:
        continue
    refs=sorted(set(re.findall(r'([A-Za-z0-9\-]+\.html)',txt)))
    matched=[r for r in refs if any(k in r for k in keywords)]
    if matched:
        page_refs[f]=matched
# summarize forms/buttons in related html
summary={}
for f in sorted([x for x in related if x.endswith('.html')]):
    txt=open(f,'r',encoding='utf-8').read()
    forms=[]
    for m in re.finditer(r'<form\b([^>]*)>(.*?)</form>',txt,re.S|re.I):
        attrs=m.group(1)
        body=m.group(2)
        aid=re.search(r'id=["\']([^"\']+)',attrs,re.I)
        action=re.search(r'action=["\']([^"\']*)',attrs,re.I)
        method=re.search(r'method=["\']([^"\']*)',attrs,re.I)
        inputs=re.findall(r'<(input|select|textarea)\b([^>]*)',body,re.I)
        names=[]
        for tag,a in inputs:
            n=re.search(r'name=["\']([^"\']+)',a,re.I)
