            names.append({'tag':tag.lower(),'name':n.group(1) if n else None,'type':t.group(1) if t else None})
        forms.append({'id':aid.group(1) if aid else None,'action':action.group(1) if action else None,'method':method.group(1) if method else None,'fields':names})
    scripts=sorted(set(re.findall(r'<script[^>]+src=["\']([^"\']+)',txt,re.I)))
    summary[f]={'forms':forms,'scripts':scripts,'title':(re.search(r'<title>(.*?)</title>',txt,re.I|re.S).group(1).strip() if re.search(r'<title>(.*?)</title>',txt,re.I|re.S) else None)}
print('RELATED FILES:')
for f in sorted(related):
    print('-',f)
print('\nPAGE REFS:')
for f in sorted(page_refs):
    print(f+':',', '.join(page_refs[f]))
print('\nFORM/SCRIPT SUMMARY JSON:')
print(json.dumps(summary,ensure_ascii=False,indent=2))
