   283	  function normalizeFlatBreadcrumb(container) {
   284	    if (!container) return;
   285	
   286	    var nodes = Array.prototype.slice.call(container.childNodes || []);
   287	    var items = [];
   288	
   289	    nodes.forEach(function (node) {
   290	      if (node.nodeType === 3) {
   291	        var text = (node.textContent || '').trim();
   292	        if (!text) return;
   293	        if (/^[\/>]+$/.test(text)) return;
   294	        items.push(node.cloneNode(true));
   295	        return;
   296	      }
   297	
   298	      if (node.nodeType !== 1) return;
   299	
   300	      var tagName = (node.tagName || '').toLowerCase();
   301	      var textContent = (node.textContent || '').trim();
   302	      var classList = node.classList || { contains: function () { return false; } };
   303	
   304	      if (tagName === 'i' && classList.contains('fa-angle-right')) return;
   305	      if ((tagName === 'span' || tagName === 'li') && /^[\/>]+$/.test(textContent)) return;
   306	
   307	      items.push(node.cloneNode(true));
   308	    });
   309	
   310	    if (items.length < 2) return;
   311	
   312	    container.innerHTML = '';
   313	    items.forEach(function (item, index) {
   314	      container.appendChild(item);
   315	      if (index >= items.length - 1) return;
   316	      var separator = document.createElement('i');
   317	      separator.className = 'fa-solid fa-angle-right';
   318	      separator.setAttribute('aria-hidden', 'true');
   319	      container.appendChild(separator);
   320	    });
   321	  }
   322	
   323	  function normalizeBreadcrumbs(scope) {
   324	    var root = scope || document;
   325	    var selectors = [
   326	      '.about-breadcrumbs',
   327	      '.jobs-breadcrumbs',
   328	      '.catalog-breadcrumbs',
   329	      '.article-breadcrumbs'
   330	    ];
   331	    selectors.forEach(function (selector) {
   332	      var list = root.querySelectorAll(selector);
   333	      list.forEach(normalizeFlatBreadcrumb);
   334	    });
   335	  }
