   162	  <script>
   163	    (function () {
   164	      var form = document.getElementById('recruitmentLeadForm');
   165	      var preview = document.getElementById('requestPreview');
   166	      var result = document.getElementById('requestResult');
   167	      var requestIdText = document.getElementById('requestIdText');
   168	      var downloadBtn = document.getElementById('downloadBriefBtn');
   169	      var zaloUrl = 'https://zalo.me/0777315188';
   170	      var lastPayload = null;
   171	
   172	      function value(id) {
   173	        var el = document.getElementById(id);
   174	        return el ? String(el.value || '').trim() : '';
   175	      }
   176	
   177	      function buildPayload() {
   178	        var timestamp = new Date();
   179	        var createdAt = timestamp.toISOString().slice(0, 19);
   180	        var requestId = 'brief-' + createdAt.replace(/[:T]/g, '-');
   181	        return {
   182	          requestId: requestId,
   183	          companyName: value('companyName'),
   184	          contactName: value('contactName'),
   185	          contactPhone: value('contactPhone'),
   186	          contactEmail: value('contactEmail'),
   187	          jobTitle: value('jobTitle'),
   188	          jobLocation: value('jobLocation'),
   189	          jobQuantity: value('jobQuantity') || '1',
   190	          jobDeadline: value('jobDeadline'),
   191	          employmentType: value('employmentType'),
   192	          workMode: value('workMode'),
   193	          salaryLabel: value('salaryLabel'),
   194	          experienceLevel: value('experienceLevel'),
   195	          jobNotes: value('jobNotes'),
   196	          sourcePage: 'dang-tin-tuyen-dung.html',
   197	          sourceChannel: 'website-brief',
   198	          createdAt: createdAt
   199	        };
   200	      }
   201	
   202	      function formatRequestCode(requestId) {
   203	        return String(requestId || '').replace(/^brief-/, 'YC-');
   204	      }
   205	
   206	      function buildDownloadName(requestId) {
   207	        return 'yeu-cau-tuyen-dung-' + formatRequestCode(requestId).toLowerCase() + '.txt';
   208	      }
   209	
   210	      function buildBrief(payload) {
   211	        return [
   212	          'Thông tin tuyển dụng gửi Diệu Tâm',
   213	          'Mã tham chiếu: ' + formatRequestCode(payload.requestId),
   214	          'Công ty: ' + payload.companyName,
   215	          'Người liên hệ: ' + payload.contactName,
   216	          'SĐT/Zalo: ' + payload.contactPhone,
   217	          'Email: ' + (payload.contactEmail || 'Chưa cung cấp'),
   218	          'Vị trí cần tuyển: ' + payload.jobTitle,
   219	          'Khu vực làm việc: ' + payload.jobLocation,
   220	          'Số lượng: ' + (payload.jobQuantity || '1'),
   221	          'Hạn nhận hồ sơ: ' + (payload.jobDeadline || 'Chưa chốt'),
   222	          'Hình thức: ' + payload.employmentType,
   223	          'Cách làm việc: ' + payload.workMode,
   224	          'Lương tham khảo: ' + (payload.salaryLabel || 'Chưa công khai'),
   225	          'Mức kinh nghiệm: ' + (payload.experienceLevel || 'Chưa ghi rõ'),
   226	          'Ghi chú thêm: ' + (payload.jobNotes || 'Không có ghi chú thêm')
   227	        ].join('\\n');
   228	      }
   229	
   230	      function downloadBrief(payload) {
   231	        var blob = new Blob([buildBrief(payload)], { type: 'text/plain;charset=utf-8' });
   232	        var href = URL.createObjectURL(blob);
   233	        var anchor = document.createElement('a');
   234	        anchor.href = href;
   235	        anchor.download = buildDownloadName(payload.requestId);
   236	        document.body.appendChild(anchor);
   237	        anchor.click();
   238	        anchor.remove();
   239	        URL.revokeObjectURL(href);
   240	      }
   241	
   242	      function submitBrief(event) {
   243	        event.preventDefault();
   244	        var payload = buildPayload();
   245	        var brief = buildBrief(payload);
   246	        lastPayload = payload;
   247	        preview.textContent = brief;
   248	        if (requestIdText) {
   249	          requestIdText.textContent = formatRequestCode(payload.requestId);
   250	        }
   251	        result.hidden = false;
   252	
   253	        if (navigator.clipboard && navigator.clipboard.writeText) {
   254	          navigator.clipboard.writeText(brief).catch(function () {});
   255	        }
   256	
   257	        window.open(zaloUrl, '_blank', 'noopener');
   258	      }
   259	
   260	      function handleDownload() {
   261	        var payload = lastPayload || buildPayload();
   262	        downloadBrief(payload);
   263	        if (requestIdText) {
   264	          requestIdText.textContent = formatRequestCode(payload.requestId);
   265	        }
   266	        preview.textContent = buildBrief(payload);
   267	        result.hidden = false;
   268	      }
   269	
   270	      if (form) {
   271	        form.addEventListener('submit', submitBrief);
   272	      }
   273	      if (downloadBtn) {
   274	        downloadBtn.addEventListener('click', handleDownload);
   275	      }
   276	    })();
   277	  </script>
